<template>
  <v-dialog
    v-model="isShown"
    width="500"
    max-width="90vw"
  >
    <v-card
      class="flex flex-col overflow-auto max-h-[90vh] visible-scroll"
      :title="t('mod.selectOrCreateGroup')"
    >
      <v-divider />
      <v-card-text class="overflow-auto pt-4">
        <!-- Search bar for filtering groups (only shown when not creating new) -->
        <v-text-field
          v-if="!creatingNew"
          v-model="searchQuery"
          :label="t('mod.searchGroups')"
          prepend-inner-icon="search"
          clearable
          autofocus
          hide-details
          density="compact"
          variant="outlined"
          class="mb-2"
        />

        <!-- New group name input (shown when creating new) -->
        <v-expand-transition>
          <div v-if="creatingNew" class="mb-4">
            <v-text-field
              v-model="newGroupName"
              :label="t('mod.groupName')"
              variant="outlined"
              density="compact"
              autofocus
              hide-details
              :rules="rules"
              @keyup.enter="onConfirmNewGroup"
            />
          </div>
        </v-expand-transition>

        <v-list dense v-if="!creatingNew" bg-color="transparent">
          <v-list-item
            @click="onCreateNew"
          >
            <template #prepend><v-avatar>
              <v-icon color="primary">
                create_new_folder
              </v-icon>
            </v-avatar></template>
            <v-list-item-title class="primary--text font-weight-bold">
                {{ t('mod.newFolder') }}
              </v-list-item-title>
</v-list-item>

          <v-list-item
            v-if="onApplyShared"
            @click="onApplySharedRules"
          >
            <template #prepend><v-avatar>
              <v-icon color="primary">
                bookmarks
              </v-icon>
            </v-avatar></template>
            <v-list-item-title class="primary--text font-weight-bold">
                {{ t('mod.applyGroupRules') }}
              </v-list-item-title>
</v-list-item>

          <v-divider v-if="filteredGroups.length > 0" class="mb-2" />

          <!-- Existing groups (filtered and sorted) -->
          <div
            v-if="filteredGroups.length > 0"
            class="overflow-auto max-h-[300px]"
          >
            <v-list-item
              v-for="g of filteredGroups"
              :key="g[0]"
              dense
              @click="onSelectGroup(g[0])"
            >
              <template #prepend><v-avatar>
                <v-icon>folder</v-icon>
              </v-avatar></template>
              <v-list-item-title>{{ displayName(g[0]) }}</v-list-item-title>
                <v-list-item-subtitle>
                  {{ countLabel(groupModCounts[g[0]] || 0) }}
                </v-list-item-subtitle>
</v-list-item>
          </div>

          <!-- No groups message -->
          <v-list-item v-else-if="Object.keys(groups).length === 0">
            <v-list-item-subtitle class="text-center">
                {{ t('mod.noGroupsYet') }}
              </v-list-item-subtitle>
</v-list-item>

          <!-- No results message -->
          <v-list-item v-else>
            <v-list-item-subtitle class="text-center">
                {{ t('mod.noGroupsFound') }}
              </v-list-item-subtitle>
</v-list-item>
        </v-list>
      </v-card-text>
      <v-divider />
      <v-card-actions>
        <v-btn
          @click="onCancel"
         variant="text">
          {{ creatingNew ? t('shared.back') : t('shared.cancel') }}
        </v-btn>
        <v-spacer />
        <v-btn
          v-if="creatingNew"
          color="primary"
          :disabled="!newGroupName.trim()"
          @click="onConfirmNewGroup"
        >
          <v-icon start>
            add
          </v-icon>
          {{ t('mod.createGroup') }}
        </v-btn>
      </v-card-actions>
    </v-card>
  </v-dialog>
</template>

<script setup lang="ts">
import { useDialog } from '@/composables/dialog'
import { getGroupDisplayName } from '@/composables/modGroup'
import { ModGroupData } from '@xmcl/runtime-api'

const { t, locale } = useI18n()
const displayName = (name: string) => getGroupDisplayName(name, t, locale.value)
const searchQuery = ref('' as string | null)
const creatingNew = ref(false)
const newGroupName = ref('')

const rules = computed(() => [(v: string) => !!v || t('mod.groupNameRequired')])

const { isShown, parameter } = useDialog<{
  groups: Record<string, ModGroupData>
  groupModCounts?: Record<string, number>
  countLabel?: (count: number) => string
  onSelect: (groupName: string | null, newName?: string) => void
  onApplyShared?: () => void
}>('mod-group-select')

const groups = computed(() => parameter.value?.groups || {})
const groupModCounts = computed(() => parameter.value?.groupModCounts || {})
const countLabel = computed(() => parameter.value?.countLabel || ((count: number) => t('mod.mods', { count })))
const onApplyShared = computed(() => parameter.value?.onApplyShared)

// Filter and sort groups alphabetically
const filteredGroups = computed(() => {
  const query = searchQuery.value?.toLowerCase().trim()
  let filtered = Object.entries(groups.value)

  if (query) {
    filtered = filtered.filter(([g]) => displayName(g).toLowerCase().includes(query))
  }

  return filtered.sort(([a], [b]) => displayName(a).localeCompare(displayName(b), locale.value, { numeric: true, sensitivity: 'base' }))
})

function onSelectGroup(groupName: string) {
  parameter.value?.onSelect(groupName)
  isShown.value = false
  reset()
}

function onCreateNew() {
  creatingNew.value = true
  newGroupName.value = ''
}

function onApplySharedRules() {
  parameter.value?.onApplyShared?.()
  isShown.value = false
  reset()
}

function onConfirmNewGroup() {
  if (newGroupName.value.trim()) {
    parameter.value?.onSelect(null, newGroupName.value.trim())
    isShown.value = false
    reset()
  }
}

function onCancel() {
  if (creatingNew.value) {
    creatingNew.value = false
    newGroupName.value = ''
  } else {
    isShown.value = false
    reset()
  }
}

function reset() {
  searchQuery.value = ''
  creatingNew.value = false
  newGroupName.value = ''
}
</script>
